<template>
  <section class="procedure-shell">
    <header><div><small>{{ $t('clinical360.procedure.eyebrow') }}</small><h2>{{ $t('clinical360.procedure.title') }}</h2><p>{{ $t('clinical360.procedure.subtitle') }}</p></div><v-btn v-if="canDocument" x-small depressed color="#0f766e" dark @click="openForm"><v-icon x-small left>mdi-medical-bag</v-icon>{{ $t('clinical360.procedure.new_record') }}</v-btn></header>
    <div class="readiness"><article v-for="item in readiness" :key="item.label" :class="item.state"><v-icon small>{{ item.icon }}</v-icon><span>{{ item.label }}</span><strong>{{ item.value }}</strong></article></div>
    <div class="procedure-layout"><section><h3>{{ $t('clinical360.procedure.safety') }}</h3><div v-for="item in checklist" :key="item.label" class="check-row"><v-icon small :color="item.done?'#047857':'#b45309'">{{ item.done?'mdi-check-circle':'mdi-alert-circle-outline' }}</v-icon><span>{{ item.label }}</span><b>{{ item.done?$t('clinical360.common.ready'):$t('clinical360.common.verify') }}</b></div></section><section><h3>{{ $t('clinical360.procedure.filed_records') }}</h3><button v-for="doc in procedureDocuments" :key="doc.id" class="record-row" @click="selectedId=doc.id"><v-icon small>mdi-clipboard-pulse-outline</v-icon><span><strong>{{ doc.title }}</strong><small>{{ format(doc.createdAt) }} · {{ doc.createdBy }}</small></span><em>{{ doc.status||$t('clinical360.common.filed') }}</em></button><p v-if="!procedureDocuments.length" class="empty">{{ $t('clinical360.procedure.no_record') }}</p></section></div>
    <article v-if="selected" class="record-detail"><header><strong>{{ selected.title }}</strong><span>{{ selected.status }}</span></header><p>{{ selected.content }}</p></article>
    <v-dialog v-model="dialog" max-width="850" persistent scrollable><v-card><v-card-title class="dialog-title">{{ $t('clinical360.procedure.dialog_title') }}<v-spacer/><v-btn icon small @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text class="pt-4">
      <div class="form-grid three"><v-select v-model="form.phase" :items="phaseOptions" :label="$t('clinical360.procedure.phase')" dense outlined/><v-text-field v-model="form.procedure" :label="$t('clinical360.procedure.procedure')" dense outlined/><v-text-field v-model="form.provider" :label="$t('clinical360.procedure.provider')" dense outlined/></div>
      <div class="form-grid three"><v-text-field v-model="form.startedAt" type="datetime-local" :label="$t('clinical360.procedure.start_time')" dense outlined/><v-select v-model="form.sedationLevel" :items="sedationOptions" :label="$t('clinical360.procedure.sedation_level')" dense outlined/><v-select v-model="form.airway" :items="airwayOptions" :label="$t('clinical360.procedure.airway')" dense outlined/></div>
      <div class="checks"><v-checkbox v-model="form.identityVerified" dense hide-details :label="$t('clinical360.procedure.identity')"/><v-checkbox v-model="form.consentVerified" dense hide-details :label="$t('clinical360.procedure.consent_verified')"/><v-checkbox v-model="form.siteMarked" dense hide-details :label="$t('clinical360.procedure.site_marked')"/><v-checkbox v-model="form.timeoutCompleted" dense hide-details :label="$t('clinical360.procedure.timeout')"/></div>
      <div class="form-grid"><v-textarea v-model="form.monitoring" :label="$t('clinical360.procedure.monitoring')" rows="3" dense outlined/><v-textarea v-model="form.outcome" :label="$t('clinical360.procedure.outcome')" rows="3" dense outlined/></div><v-textarea v-model="form.handoff" :label="$t('clinical360.procedure.handoff')" rows="2" dense outlined/>
    </v-card-text><v-card-actions><v-spacer/><v-btn text small @click="dialog=false">{{ $t('clinical360.common.cancel') }}</v-btn><v-btn small depressed color="#0f766e" dark :disabled="!form.procedure" :loading="saving" @click="save">{{ $t('clinical360.procedure.save') }}</v-btn></v-card-actions></v-card></v-dialog>
  </section>
</template>
<script>
export default{name:'Patient360ProcedureTab',props:{patientId:{type:String,required:true},patient:{type:Object,default:()=>({})},documents:{type:Array,default:()=>[]},tasks:{type:Array,default:()=>[]},role:{type:String,default:''},readOnly:Boolean},data:()=>({dialog:false,saving:false,selectedId:'',form:{}}),computed:{canDocument(){return !this.readOnly&&['ADMIN','DOCTOR','NP','NURSE','MAJOR_SERVICE','NURSING_SUPERVISOR'].includes(this.role)},isFrench(){return this.$i18n.locale==='fr'},phaseOptions(){const labels=this.isFrench?['Pré-procédure','Pendant la procédure','Récupération','Relève post-procédure']:['Pre-procedure','Intra-procedure','Recovery','Post-procedure handoff'];return['Pre-procedure','Intra-procedure','Recovery','Post-procedure handoff'].map((value,index)=>({value,text:labels[index]}))},sedationOptions(){const labels=this.isFrench?['Aucune','Minimale','Modérée','Profonde','Anesthésie générale']:['None','Minimal','Moderate','Deep','General anesthesia'];return['None','Minimal','Moderate','Deep','General anesthesia'].map((value,index)=>({value,text:labels[index]}))},airwayOptions(){const labels=this.isFrench?['Respiration spontanée','Masque à oxygène','Lunettes nasales','Masque laryngé','Tube endotrachéal','Trachéotomie']:['Spontaneous','Oxygen mask','Nasal cannula','LMA','Endotracheal tube','Tracheostomy'];return['Spontaneous','Oxygen mask','Nasal cannula','LMA','Endotracheal tube','Tracheostomy'].map((value,index)=>({value,text:labels[index]}))},procedureDocuments(){return this.documents.filter(x=>/procedure|sedation|anesthesia|anaesthesia/i.test(`${x.category} ${x.title}`))},selected(){return this.procedureDocuments.find(x=>x.id===this.selectedId)||this.procedureDocuments[0]||null},readiness(){const handoff=this.procedureDocuments.some(x=>/recovery|handoff/i.test(x.content||''));return[{label:this.$t('clinical360.procedure.consent'),value:this.patient.consentStatus||this.$t('clinical360.common.verify'),state:this.patient.consentStatus?'good':'warning',icon:'mdi-file-sign'},{label:this.$t('clinical360.procedure.allergies'),value:this.patient.allergies||this.$t('clinical360.common.verify'),state:this.patient.allergies?'good':'warning',icon:'mdi-allergy'},{label:this.$t('clinical360.procedure.open_tasks'),value:String(this.tasks.filter(x=>!/done|complete/i.test(x.status||'')).length),state:this.tasks.length?'warning':'good',icon:'mdi-format-list-checks'},{label:this.$t('clinical360.procedure.recovery_handoff'),value:handoff?this.$t('clinical360.common.filed'):this.$t('clinical360.common.due'),state:handoff?'good':'warning',icon:'mdi-account-switch'}]},checklist(){return[{label:this.$t('clinical360.procedure.patient_verified'),done:Boolean(this.patient.mrn)},{label:this.$t('clinical360.procedure.consent_site'),done:Boolean(this.patient.consentStatus)},{label:this.$t('clinical360.procedure.allergy_review'),done:Boolean(this.patient.allergies)},{label:this.$t('clinical360.procedure.recovery_destination'),done:this.procedureDocuments.length>0}]}},methods:{format(v){return v?new Date(v).toLocaleString(this.$i18n.locale==='fr'?'fr-CM':'en-US'):'-'},openForm(){this.form={phase:'Pre-procedure',procedure:'',provider:this.patient.provider||this.patient.attending||'',startedAt:new Date().toISOString().slice(0,16),sedationLevel:'None',airway:'Spontaneous',identityVerified:false,consentVerified:false,siteMarked:false,timeoutCompleted:false,monitoring:'',outcome:'',handoff:''};this.dialog=true},async save(){this.saving=true;try{const f=this.form;const content=[`Phase: ${f.phase}`,`Provider: ${f.provider||'-'}`,`Started: ${f.startedAt}`,`Sedation: ${f.sedationLevel}`,`Airway: ${f.airway}`,`Safety: identity ${f.identityVerified?'verified':'not verified'}, consent ${f.consentVerified?'verified':'not verified'}, site ${f.siteMarked?'marked':'not marked'}, timeout ${f.timeoutCompleted?'completed':'not completed'}`,`Monitoring: ${f.monitoring||'-'}`,`Outcome: ${f.outcome||'-'}`,`Handoff: ${f.handoff||'-'}`].join('\n');await this.$store.dispatch('clinical/createDocument',{patientId:this.patientId,title:`${f.phase} - ${f.procedure}`,category:'Sedation / Procedure',content,status:'Filed',procedurePhase:f.phase});this.dialog=false;this.$emit('saved',this.$t('clinical360.procedure.save_success'))}finally{this.saving=false}}}}
</script>
<style scoped>
.procedure-shell{padding:14px;background:#f8fbfb;min-height:100%}.procedure-shell>header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #0f766e;padding-bottom:10px}.procedure-shell small{font-weight:900;color:#64748b}.procedure-shell h2{font-size:18px;margin:2px 0}.procedure-shell p{margin:0;font-size:12px}.readiness{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:11px 0}.readiness article{display:grid;grid-template-columns:24px 1fr;gap:3px;padding:9px;border-left:3px solid #b45309;background:white}.readiness article.good{border-color:#047857}.readiness strong{grid-column:2;font-size:12px}.procedure-layout{display:grid;grid-template-columns:1fr 1.2fr;border:1px solid #cbd5e1;background:white}.procedure-layout section{padding:12px;border-right:1px solid #e2e8f0}.procedure-layout h3{font-size:13px;color:#0f766e}.check-row,.record-row{display:grid;grid-template-columns:24px 1fr auto;gap:7px;align-items:center;border-bottom:1px solid #e2e8f0;padding:8px;width:100%;text-align:left;font-size:12px}.record-row span{display:flex;flex-direction:column}.record-row small,.record-row em{color:#64748b;font-size:11px}.record-detail{margin-top:10px;border:1px solid #cbd5e1;background:white;padding:12px}.record-detail header{display:flex;justify-content:space-between}.record-detail p{white-space:pre-wrap;font-size:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form-grid.three{grid-template-columns:repeat(3,1fr)}.checks{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:14px}.dialog-title{font-size:16px!important;font-weight:900}.empty{color:#64748b;font-size:12px}@media(max-width:800px){.readiness{grid-template-columns:1fr 1fr}.procedure-layout,.form-grid,.form-grid.three{grid-template-columns:1fr}}
</style>
